   private boolean isFriendNearBlock(BlockPos blockPos) {
      if (gameInstance.world != null && gameInstance.player != null && BiConsumerImpl.й != null) {
         Vec3d vec3d = new Vec3d(blockPos.getX() + crystalPlaceOffsetX, blockPos.getY() + 1.0, blockPos.getZ() + crystalPlaceOffsetZ);
         double d0 = this.checkRadiusOption.get().doubleValue();
         double d1 = d0 * d0;

         for (PlayerEntity м3 : gameInstance.world.getPlayers()) {
            if (м3 != gameInstance.player && BiConsumerImpl.й.contains(м3.getName().getString()) && м3.getPositionVec().squareDistanceTo(vec3d) <= d1) {
               return true;
            }
         }

         return false;
      } else {
         return false;
      }
   }

   public AutoCrystalModule() {
      this.doNotExplodeSubOptions = new MultiBoxSetting(
         doNotExplodeRuLabel,
         doNotExplodeLabel,
         new BooleanSetting(selfLabel, true, friendsLabel),
         new BooleanSetting(placeCrystalAndObsidianRuLabel, false, placeCrystalAndObsidianLabel),
         new BooleanSetting(placeCrystalRuLabel, true, itemsLabel)
      );
      this.checkRadiusOption = new FloatSliderSetting(checkRadiusRuLabel, radiusDefault, 1.0F, radiusMax, radiusStep, checkRadiusLabel);
      this.modeOption = new BooleanSetting(placeObsAndCrystalRuLabel2, false, placeCrystalLabel);
      this.placeCrystalButton = new BindSetting(placeCrystalRuLabel2, 0, placeCrystalLabel2, null).withSupplier(() -> !this.modeOption.getValue());
      this.obsidianButton = new BindSetting(obsidianRuLabel, 0, obsidianLabel, null).withSupplier(() -> this.modeOption.getValue());
      this.crystalButton = new BindSetting(crystalRuLabel, 0, crystalLabel, null).withSupplier(() -> this.modeOption.getValue());
      this.crystalSourceMode = new ModeSetting(crystalSourceRuLabel, crystalSourceLabel, inHandHotbarRuLabel, inHandHotbarLabel2, inHandHotbarLabel)
         .setVisibility(() -> !this.modeOption.getValue());
      this.addSettings(
         new AbstractModuleSetting[]{
            this.doNotExplodeSubOptions,
            this.checkRadiusOption,
            this.modeOption,
            this.placeCrystalButton,
            this.obsidianButton,
            this.crystalButton,
            this.crystalSourceMode
         }
      );
   }

   private void switchSlotAndRun(int i, Runnable runnable) {
      int j = gameInstance.player.inventory.currentItem;
      if (i < 9) {
         gameInstance.player.inventory.currentItem = i;
         gameInstance.playerController.syncCurrentPlayItem();
         runnable.run();
         gameInstance.player.inventory.currentItem = j;
         gameInstance.playerController.syncCurrentPlayItem();
      } else {
         int k = gameInstance.player.openContainer.windowId;
         gameInstance.playerController.windowClick(k, i, j, ClickType.SWAP, gameInstance.player);
         runnable.run();
         gameInstance.playerController.windowClick(k, i, j, ClickType.SWAP, gameInstance.player);
      }
   }

   private Vec3d clampVecToAABB(Vec3d vec3d, Box Box) {
      return new Vec3d(MathHelper.clamp(vec3d.x, Box.minX, Box.maxX), MathHelper.clamp(vec3d.y, Box.minY, Box.maxY), MathHelper.clamp(vec3d.z, Box.minZ, Box.maxZ));
   }

   private boolean shouldTargetEntity(Entity entity) {
      if (entity == null) {
         return false;
      } else {
         BlockPos blockPos = new BlockPos(entity.getPositionVec());
         return this.doNotExplodeSubOptions.isCheckedByNameOnly(friendsCheckKey) && this.isFriendNearBlock(blockPos)
            ? false
            : !this.doNotExplodeSubOptions.isCheckedByNameOnly(itemsCheckKey) || !this.method9068(blockPos);
      }
   }

   public Vec3d getPlaceVecClamped(Vec3d vec3d, Entity entity) {
      return this.clampVecToAABB(vec3d, entity.getBoundingBox());
   }

