   private boolean method9068(BlockPos blockPos) {
      if (gameInstance.world == null) {
         return false;
      } else {
         double d0 = this.checkRadiusOption.get().doubleValue();
         Box Box = new Box(blockPos.getX() - d0, blockPos.getY() - d0, blockPos.getZ() - d0, blockPos.getX() + d0 + 1.0, blockPos.getY() + d0 + aimYawOffset, blockPos.getZ() + d0 + 1.0);

         for (Entity entity : gameInstance.world.getEntitiesWithinAABBExcludingEntity(null, Box)) {
            if (entity instanceof ItemEntity) {
               ItemEntity ItemEntity = (ItemEntity)entity;
               Item Item = ItemEntity.getItem().getItem();
               if (Item == Items.NETHERITE_HELMET
                  || Item == Items.NETHERITE_CHESTPLATE
                  || Item == Items.NETHERITE_LEGGINGS
                  || Item == Items.NETHERITE_BOOTS
                  || Item == Items.DIAMOND_HELMET
                  || Item == Items.DIAMOND_CHESTPLATE
                  || Item == Items.DIAMOND_LEGGINGS
                  || Item == Items.DIAMOND_BOOTS
                  || Item == Items.NETHERITE_SWORD
                  || Item == Items.DIAMOND_SWORD
                  || Item == Items.NETHERITE_PICKAXE
                  || Item == Items.DIAMOND_PICKAXE
                  || Item == Items.NETHERITE_SHOVEL
                  || Item == Items.DIAMOND_SHOVEL
                  || Item == Items.NETHERITE_AXE
                  || Item == Items.DIAMOND_AXE
                  || Item == Items.TOTEM_OF_UNDYING
                  || Item == Items.END_CRYSTAL
                  || Item == Items.ENCHANTED_GOLDEN_APPLE
                  || Item == Items.GOLDEN_APPLE
                  || Item == Items.ENDER_PEARL
                  || Item == Items.TRIDENT
                  || Item == Items.CROSSBOW
                  || Item == Items.ELYTRA) {
                  return true;
               }
            }
         }

         return false;
      }
   }

