   private void onKeyInputEvent(IntValuePredicate intvaluepredicate) {
      if (gameInstance.currentScreen == null) {
         int i = intvaluepredicate.getValue();
         if (this.modeOption.getValue()) {
            if (i == this.crystalButton.getKeyCode()) {
               this.tryAttackCrystal();
            } else {
               if (i == this.obsidianButton.getKeyCode()) {
                  this.placeCrystal();
               }
            }
         } else {
            if (this.placeCrystalButton.getKeyCode() != 0 && i == this.placeCrystalButton.getKeyCode()) {
               this.tryAttackCrystal();
            }
         }
      }
   }

   public Vec3d getAimVecToEntity(Entity entity) {
      Vec3d vec3d = gameInstance.player.getEyePosition(gameInstance.getRenderPartialTicks());
      return this.getPlaceVecClamped(vec3d, entity).subtract(vec3d);
   }

   private void placeBlockAt(BlockPos blockPos, Direction Direction, Hand Hand) {
      Vec3d vec3d = new Vec3d(blockPos.getX() + aimPitchRange, blockPos.getY() + 1.0, blockPos.getZ() + attackAimPitchRange);
      BlockRayTraceResult BlockRayTraceResult = new BlockRayTraceResult(vec3d, Direction, blockPos, false);
      gameInstance.playerController.processRightClickBlock(gameInstance.player, gameInstance.world, Hand, BlockRayTraceResult);
      gameInstance.player.swingArm(Hand);
   }

   private boolean canPlaceCrystalAt(BlockPos blockPos) {
      if (blockPos == null) {
         return false;
      } else if (this.doNotExplodeSubOptions.isCheckedByNameOnly(selfKey) && gameInstance.player.getPosY() > blockPos.getY()) {
         return false;
      } else {
         return this.doNotExplodeSubOptions.isCheckedByNameOnly(friendsKey) && this.isFriendNearBlock(blockPos)
            ? false
            : !this.doNotExplodeSubOptions.isCheckedByNameOnly(itemsKey) || !this.method9068(blockPos);
      }
   }

   private void placeObsidian() {
      if (this.needRestoreSlot) {
         this.needRestoreSlot = false;
         gameInstance.player.inventory.currentItem = this.savedHotbarSlot;
         gameInstance.playerController.syncCurrentPlayItem();
      } else if (this.targetBlockPos != null) {
         if (gameInstance.world.getBlockState(this.targetBlockPos).isAir()) {
            this.targetBlockPos = null;
         } else if (this.justPlaced) {
            this.justPlaced = false;
         } else {
            if (!this.canPlaceCrystalAt(this.targetBlockPos)) {
               this.targetBlockPos = null;
               return;
            }

            Vec3d дыxxx = gameInstance.player.getEyePosition(1.0F);
            Vec3d дыx = this.clampVecToAABB(дыxxx, new Box(this.targetBlockPos));
            Vec3d дыxx = дыx.subtract(дыxxx);
            float f = (float)MathHelper.wrapDegrees(Math.toDegrees(Math.atan2(дыxx.z, дыxx.x)) - rotationYawOffset);
            float f1 = (float)(-Math.toDegrees(Math.atan2(дыxx.y, Math.hypot(дыxx.x, дыxx.z))));
            RotationHelper.aimAtSimple(new Rotation(f, f1), placeAimSpeed, placeAimFov, 1, 6);
            this.savedHotbarSlot = gameInstance.player.inventory.currentItem;
            gameInstance.player.inventory.currentItem = this.crystalSlot;
            gameInstance.playerController.syncCurrentPlayItem();
            дыxx = дыxx.inverse();
            gameInstance.playerController
               .processRightClickBlock(
                  gameInstance.player, gameInstance.world, Hand.MAIN_HAND, new BlockRayTraceResult(дыx, Direction.getFacingFromVector(дыxx.x, дыxx.y, дыxx.z), this.targetBlockPos, false)
               );
            gameInstance.player.swingArm(Hand.MAIN_HAND);
            this.updateCrystalBoundingBox(this.targetBlockPos);
            this.needRestoreSlot = true;
            this.targetBlockPos = null;
         }
      }

      if (this.crystalBoundingBox != null) {
         for (Entity entity : gameInstance.world.getAllEntities()) {
            if (entity instanceof SgClass249 && this.crystalBoundingBox.contains(entity.getPositionVec())) {
               if (!this.shouldTargetEntity(entity)) {
                  this.crystalBoundingBox = null;
                  return;
               }

               if (!entity.getBoundingBox().contains(gameInstance.player.getEyePosition(1.0F))) {
                  Vec3d vec3d = this.getAimVecToEntity(entity);
                  float f2 = (float)MathHelper.wrapDegrees(Math.toDegrees(Math.atan2(vec3d.z, vec3d.x)) - attackAimYawOffset);
                  float f3 = (float)(-Math.toDegrees(Math.atan2(vec3d.y, Math.hypot(vec3d.x, vec3d.z))));
                  RotationHelper.aimAtSimple(new Rotation(f2, f3), attackAimSpeed, attackAimFov, 1, 6);
               }

               gameInstance.playerController.attackEntity(gameInstance.player, entity);
               gameInstance.player.swingArm(Hand.MAIN_HAND);
               this.crystalBoundingBox = null;
               return;
            }
         }
      }
   }

   @Override
   public void onEvent(Event event) {
      if (gameInstance.player != null && gameInstance.world != null && gameInstance.playerController != null) {
         if (event instanceof BiomeDataEntry) {
            BiomeDataEntry biomedataentry = (BiomeDataEntry)event;
            this.onObsidianPlaceEvent(biomedataentry);
         }

         if (event instanceof ClientTickEvent) {
            this.placeObsidian();
         }

         if (event instanceof IntValuePredicate) {
            IntValuePredicate intvaluepredicate = (IntValuePredicate)event;
            this.onKeyInputEvent(intvaluepredicate);
         }

         if (event instanceof IntPredicateConsumer) {
            IntPredicateConsumer intpredicateconsumer = (IntPredicateConsumer)event;
            this.onGameTickEvent(intpredicateconsumer);
         }
      }
   }

   private void onObsidianPlaceEvent(BiomeDataEntry biomedataentry) {
      if (biomedataentry.method3276() == Blocks.OBSIDIAN) {
         if (!gameInstance.player.getCooldownTracker().hasCooldown(Items.END_CRYSTAL)) {
            int i = InventoryUtil.findItemSlotFull(Items.END_CRYSTAL);
            if (i != -1) {
               if (i < 9) {
                  this.targetBlockPos = biomedataentry.getPosition();
                  this.crystalSlot = i;
               }

               this.justPlaced = true;
            }
         }
      }
   }

